#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <span>
#include <vector>

// Counts the returns closer than limit_m; a range of 0 means the beam saw nothing.
[[nodiscard]] std::ptrdiff_t count_close(std::span<const double> ranges_m, double limit_m) {
  return std::ranges::count_if(ranges_m, [limit_m](double r) { return r > 0.0 && r < limit_m; });
}

int main() {
  const std::vector<double> scan{0.0, 0.4, 1.2, 0.8, 3.5};
  std::cout << std::format("close returns: {}\n", count_close(scan, 1.0));

  double limit_m = 1.0;
  const auto by_value = [limit_m](double r) { return r > 0.0 && r < limit_m; };       // copies 1.0 now
  const auto by_reference = [&limit_m](double r) { return r > 0.0 && r < limit_m; };  // reads limit_m at each call
  limit_m = 2.0;
  std::cout << std::format("by value: {}, by reference: {}\n", std::ranges::count_if(scan, by_value),
                           std::ranges::count_if(scan, by_reference));
}

