#include <algorithm>
#include <cstdint>
#include <format>
#include <iostream>
#include <iterator>
#include <numeric>
#include <string_view>
#include <vector>

struct Detection {
  std::int64_t id;
  double range_m;
  double confidence;
};

void show(std::string_view label, const std::vector<Detection>& ds) {
  std::cout << label << ':';
  for (const Detection& d : ds) std::cout << std::format(" {}@{}m", d.id, d.range_m);
  std::cout << '\n';
}

int main() {
  std::vector<Detection> ds{{.id = 1, .range_m = 4.2, .confidence = 0.95}, {.id = 2, .range_m = 0.8, .confidence = 0.40},
                            {.id = 3, .range_m = 2.5, .confidence = 0.91}, {.id = 4, .range_m = 1.7, .confidence = 0.88},
                            {.id = 5, .range_m = 6.0, .confidence = 0.30}};

  const auto confident = [](const Detection& d) { return d.confidence >= 0.5; };
  std::cout << std::format("confident: {} of {}, any closer than 1 m: {}\n", std::ranges::count_if(ds, confident),
                           ds.size(), std::ranges::any_of(ds, [](const Detection& d) { return d.range_m < 1.0; }));

  const auto best = std::ranges::max_element(ds, {}, &Detection::confidence);  // projection: compare confidences
  std::cout << std::format("most confident: {}\n", best->id);

  std::ranges::sort(ds, {}, &Detection::range_m);  // nearest first
  show("by range", ds);
  const auto from_2m = std::ranges::lower_bound(ds, 2.0, {}, &Detection::range_m);  // needs the same order
  std::cout << std::format("first at or beyond 2 m: {}\n", from_2m->id);

  std::ranges::stable_partition(ds, confident);  // confident first, each group still nearest first
  show("confident first", ds);

  const double total_m = std::accumulate(ds.begin(), ds.end(), 0.0, [](double sum, const Detection& d) { return sum + d.range_m; });
  std::vector<std::int64_t> ids;
  std::ranges::transform(ds, std::back_inserter(ids), &Detection::id);
  std::cout << std::format("sum of ranges {:.1f} m, {} ids copied\n", total_m, ids.size());

  const auto erased = std::erase_if(ds, [](const Detection& d) { return d.confidence < 0.5; });
  show(std::format("erased {}", erased), ds);
}

