struct Reading {
  std::int64_t stamp_ms;
  double range_m;
  bool valid;
};

// 1. Removes the invalid readings and says how many there were.
[[nodiscard]] std::ptrdiff_t drop_invalid(std::vector<Reading>& readings) {
  return static_cast<std::ptrdiff_t>(std::erase_if(readings, [](const Reading& r) { return !r.valid; }));
}

// 2. The closest reading, if there is one.
[[nodiscard]] std::optional<Reading> nearest(std::span<const Reading> readings) {
  const auto it = std::ranges::min_element(readings, {}, &Reading::range_m);
  if (it == readings.end()) return std::nullopt;
  return *it;
}

// 3. The first reading at or after stamp_ms, in readings sorted by stamp.
[[nodiscard]] std::optional<Reading> first_from(std::span<const Reading> readings, std::int64_t stamp_ms) {
  const auto it = std::ranges::lower_bound(readings, stamp_ms, {}, &Reading::stamp_ms);
  if (it == readings.end()) return std::nullopt;
  return *it;
}

// 4. The mean range, if there are readings.
[[nodiscard]] std::optional<double> mean_range(std::span<const Reading> readings) {
  if (readings.empty()) return std::nullopt;
  const double sum = std::accumulate(readings.begin(), readings.end(), 0.0,
                                     [](double total, const Reading& r) { return total + r.range_m; });
  return sum / static_cast<double>(readings.size());
}

// 5. Puts the readings closer than limit_m first, keeping the time order in both groups,
//    and returns how many are close.
[[nodiscard]] std::ptrdiff_t close_first(std::vector<Reading>& readings, double limit_m) {
  const auto far = std::ranges::stable_partition(readings, [limit_m](const Reading& r) { return r.range_m < limit_m; });
  return std::distance(readings.begin(), far.begin());
}

// 6. The stamps, in the current order.
[[nodiscard]] std::vector<std::int64_t> stamps(std::span<const Reading> readings) {
  std::vector<std::int64_t> out;
  out.reserve(readings.size());
  std::ranges::transform(readings, std::back_inserter(out), &Reading::stamp_ms);
  return out;
}

[[nodiscard]] std::string show(const std::optional<Reading>& r) {
  return r ? std::format("{} ms at {} m", r->stamp_ms, r->range_m) : "none";
}

int main() {
  std::vector<Reading> log{{.stamp_ms = 100, .range_m = 2.4, .valid = true}, {.stamp_ms = 200, .range_m = 0.0, .valid = false},
                           {.stamp_ms = 300, .range_m = 0.9, .valid = true}, {.stamp_ms = 400, .range_m = 3.1, .valid = true},
                           {.stamp_ms = 500, .range_m = 0.6, .valid = true}};
  std::cout << std::format("dropped {} invalid\n", drop_invalid(log));
  std::cout << std::format("nearest: {}\n", show(nearest(log)));
  std::cout << std::format("first from 250 ms: {}\n", show(first_from(log, 250)));
  std::cout << std::format("first from 600 ms: {}\n", show(first_from(log, 600)));
  std::cout << std::format("mean range: {:.2f} m\n", mean_range(log).value_or(0.0));
  std::cout << std::format("mean of nothing: {}\n", mean_range({}).has_value() ? "a value" : "no value");
  const std::ptrdiff_t close = close_first(log, 1.0);
  std::cout << std::format("{} close, stamps now:", close);
  for (const std::int64_t s : stamps(log)) std::cout << ' ' << s;
  std::cout << '\n';
}

