struct Job {
  std::string name;
  std::int32_t priority;  // higher runs first
  std::int64_t deadline_ms;
};

void show(std::string_view label, const std::vector<Job>& jobs) {
  std::cout << std::format("{:<24}", label);
  for (const Job& j : jobs) std::cout << ' ' << j.name;
  std::cout << '\n';
}

int main() {
  const std::vector<Job> jobs{{.name = "charge", .priority = 1, .deadline_ms = 900},
                              {.name = "deliver", .priority = 3, .deadline_ms = 500},
                              {.name = "inspect", .priority = 3, .deadline_ms = 200},
                              {.name = "map", .priority = 2, .deadline_ms = 100}};

  auto by_deadline = jobs;
  std::ranges::sort(by_deadline, {}, &Job::deadline_ms);  // one key: a projection and the default <
  show("deadline", by_deadline);

  auto by_priority = jobs;
  std::ranges::stable_sort(by_priority, std::ranges::greater{}, &Job::priority);  // descending; ties keep input order
  show("priority, descending", by_priority);

  // Two keys: priority descending, then deadline ascending. std::tie compares the
  // priorities first, and the deadlines only when the priorities are equal.
  auto by_both = jobs;
  std::ranges::sort(by_both, [](const Job& a, const Job& b) {
    return std::tie(b.priority, a.deadline_ms) < std::tie(a.priority, b.deadline_ms);
  });
  show("priority, then deadline", by_both);
}

