struct Cell {
  int x;
  int y;
};

// Meant as "by x, then by y". It says (1, 2) < (2, 1) and (2, 1) < (1, 2).
struct BadLess {
  bool operator()(const Cell& a, const Cell& b) const { return a.x < b.x || a.y < b.y; }
};

int main() {
  const std::set<Cell, BadLess> visited{{1, 2}, {2, 1}, {0, 5}, {3, 0}};
  std::cout << std::format("size {}, contains (2, 1): {}\n", visited.size(), visited.contains({2, 1}));
  for (const Cell& c : visited) std::cout << std::format("({}, {}) ", c.x, c.y);
  std::cout << '\n';
}

#include <cmath>
#include <compare>
#include <format>
#include <iostream>
#include <limits>
#include <set>

int main() {
  // REP 117 gives a laser reading three special values: +Inf for a beam with no return,
  // -Inf for a target too close to measure, and a quiet NaN for a reading the driver can't trust.
  constexpr double bad_reading = std::numeric_limits<double>::quiet_NaN();
  std::set<double> ranges_m{bad_reading};
  ranges_m.insert(1.5);
  ranges_m.insert(0.7);
  std::cout << std::format("size {}, contains 1.5: {}, contains 42.0: {}\n", ranges_m.size(), ranges_m.contains(1.5),
                           ranges_m.contains(42.0));

  // std::strong_order gives every value a place, and a NaN's sign bit decides which end it goes to.
  const double negative_nan = std::copysign(bad_reading, -1.0);
  const auto by_strong_order = [](double a, double b) { return std::strong_order(a, b) < 0; };
  std::set<double, decltype(by_strong_order)> ordered(by_strong_order);
  for (const double v : {1.5, 0.7, bad_reading, negative_nan}) ordered.insert(v);
  std::cout << std::format("strong_order: size {}, sign bit of quiet_NaN() {}, of the copysign NaN {}\n",
                           ordered.size(), std::signbit(bad_reading), std::signbit(negative_nan));
  std::cout << std::format("first is a NaN: {}, last is a NaN: {}\n", std::isnan(*ordered.begin()),
                           std::isnan(*ordered.rbegin()));
}

