struct Task {
  std::string name;
  std::int32_t priority;
};

struct ByPriority {
  bool operator()(const Task* a, const Task* b) const { return a->priority < b->priority; }
};

int main() {
  std::vector<Task> tasks{{.name = "charge", .priority = 1}, {.name = "deliver", .priority = 5}, {.name = "inspect", .priority = 9}};
  std::set<const Task*, ByPriority> queue;
  for (const Task& t : tasks) queue.insert(&t);
  tasks[0].priority = 10;  // changes the key of an element that is already in the set
  const auto erased = queue.erase(&tasks[0]);
  std::cout << std::format("erased {}, {} still queued, first in order: {}\n", erased, queue.size(), (*queue.begin())->name);
}

