// What the compiler writes for [limit_m](double r) { return r < limit_m; }, apart from the name.
class CloserThan {
 public:
  explicit CloserThan(double limit_m) : limit_m_(limit_m) {}
  bool operator()(double r) const { return r < limit_m_; }

 private:
  double limit_m_;
};

int main() {
  const std::vector<double> scan{0.4, 1.2, 0.8, 3.5};
  const double limit_m = 1.0;
  std::cout << std::format("class: {}, lambda: {}\n", std::ranges::count_if(scan, CloserThan(limit_m)),
                           std::ranges::count_if(scan, [limit_m](double r) { return r < limit_m; }));

  // Init capture: the lambda owns what it captures, here by moving a unique_ptr in.
  auto buffer = std::make_unique<std::vector<double>>(scan);
  const auto count_buffered = [owned = std::move(buffer)] { return owned->size(); };
  std::cout << std::format("buffered {}, local pointer now {}\n", count_buffered(), buffer ? "set" : "empty");

  // mutable: the call operator may change the lambda's own copy of its captures.
  auto next_id = [id = 0]() mutable { return ++id; };
  auto copy = next_id;  // a copy of the lambda, counter included
  const int first = next_id();
  const int second = next_id();
  const int from_copy = copy();
  std::cout << std::format("ids {} {}, the copy's {}\n", first, second, from_copy);

  // Generic lambda: auto parameters make the call operator a template.
  const auto largest = [](const auto& values) { return std::ranges::max(values); };
  std::cout << std::format("largest {} and {}\n", largest(scan), largest(std::vector<std::string>{"imu", "lidar", "gps"}));

  // Immediately invoked: computes a const value that needs several statements.
  const std::vector<double> sorted_scan = [&] {
    std::vector<double> s = scan;
    std::ranges::sort(s);
    return s;
  }();
  std::cout << std::format("nearest {}\n", sorted_scan.front());
}

#include <array>
