// Whether std::function keeps its target inside its own 32 bytes or on the heap.
template <typename F>
[[nodiscard]] bool stored_inside(const std::function<int(int)>& f) {
  const auto begin = reinterpret_cast<std::uintptr_t>(&f);
  const auto target = reinterpret_cast<std::uintptr_t>(f.target<F>());
  return target >= begin && target < begin + sizeof(f);
}

template <typename F>
void report(std::string_view captures, const F& lambda) {
  const std::function<int(int)> f = lambda;
  std::cout << std::format("{:<16} lambda {:>2} bytes, stored {}\n", captures, sizeof(lambda),
                           stored_inside<F>(f) ? "inside" : "on the heap");
}

int main() {
  const int offset = 3;
  const double scale = 2.0;
  const std::array<std::int64_t, 4> table{1, 2, 3, 4};
  const auto shared = std::make_shared<int>(4);
  report("[]", [](int x) { return x + 1; });
  report("[offset]", [offset](int x) { return x + offset; });
  report("[&offset]", [&offset](int x) { return x + offset; });
  report("[offset, scale]", [offset, scale](int x) { return static_cast<int>(x * scale) + offset; });
  report("[table]", [table](int x) { return x + static_cast<int>(table[1]); });
  report("[shared]", [shared](int x) { return x + *shared; });
  std::cout << std::format("std::function<int(int)> {} bytes, a function pointer {} bytes\n",
                           sizeof(std::function<int(int)>), sizeof(int (*)(int)));
}

