// Accepts the first event and every event at least min_gap_ms after the last accepted one.
[[nodiscard]] auto make_debouncer(std::int64_t min_gap_ms) {
  return [min_gap_ms, last_ms = std::optional<std::int64_t>{}](std::int64_t stamp_ms) mutable {
    if (last_ms && stamp_ms - *last_ms < min_gap_ms) return false;
    last_ms = stamp_ms;
    return true;
  };
}

int main() {
  const std::vector<std::int64_t> bumper_ms{0, 3, 7, 120, 124, 400};
  auto debounce = make_debouncer(50);

  std::vector<std::int64_t> hits;
  std::copy_if(bumper_ms.begin(), bumper_ms.end(), std::back_inserter(hits), debounce);  // works on a copy
  const auto print_all = [](const auto& values) {
    for (const auto& v : values) std::cout << v << ' ';
    std::cout << '\n';
  };
  print_all(hits);
  std::cout << std::format("original debouncer accepts 405: {}\n", debounce(405));

  std::vector<std::int64_t> shared_hits;
  auto shared = make_debouncer(50);
  std::copy_if(bumper_ms.begin(), bumper_ms.end(), std::back_inserter(shared_hits), std::ref(shared));  // uses shared
  std::cout << std::format("shared debouncer accepts 405: {}\n", shared(405));
  print_all(std::vector<std::string>{"left", "right"});

  const std::function<bool(std::int64_t)> stored = make_debouncer(50);
  std::cout << std::format("debouncer {} bytes, std::function {} bytes\n", sizeof(debounce), sizeof(stored));
}

